mapper.select:
select * from ( select *
				from Zaam_Room_History
				where userid = #{Username}
				order by endtime DESC
				)
				where ROWNUM <= 1

	
select avg(sleeptimetime) from Zaam_User_History
group by roomid
having roomid = #{roomid}

	
select sum(sleeptimetime) from Zaam_User_History
group by roomhistorynum
having roomhistorynum = #{roomhistorynum}
